FIELDS = ["title", "focus", "view", "benefit", "mechanism", "example", "risk", "risk_why", "risk_example", "cause", "action", "implementation", "event", "activity", "item", "summary_vi", "phrases"]

def scenarios():
    out = []
    for topic, _ in TOPICS:
        assert len(ROWS[topic]) == 10
        for i, values in enumerate(ROWS[topic]):
            assert len(values) == len(FIELDS), (topic, i, len(values))
            out.append(dict(zip(FIELDS, values), topic=topic, number=i + 1, id=f"{topic}-{i + 1:02}"))
    return out
